function readLanguage(): Language {
  try {
    const saved = localStorage.getItem(KEY)
    if (saved === 'zh-CN' || saved === 'en') return saved
  } catch { /* private mode */ }
  // Node's navigator.language mirrors the OS locale, which would make unit
  // tests assert against whichever language the CI machine speaks. Pin the
  // tests to English; the browser path still follows the system language.
  if (typeof process !== 'undefined' && process.env?.VITEST) return 'en'
  return typeof navigator !== 'undefined' && navigator.language.toLowerCase().startsWith('zh') ? 'zh-CN' : 'en'
}

export function language(): Language { return readLanguage() }

export function setLanguage(next: Language): void {
  try { localStorage.setItem(KEY, next) } catch { /* private mode */ }
  for (const listener of listeners) listener()
}

export function tr(text: string, lang = readLanguage()): string {
  return lang === 'zh-CN' ? (ZH[text] ?? text) : text
}

export function useLanguage(): Language {
  return useSyncExternalStore(
    (listener) => { listeners.add(listener); return () => listeners.delete(listener) },
    readLanguage,
    () => 'en',
  )
}

export function useT(): (text: string) => string {
  useLanguage()
  return (text: string) => tr(text)
}
